// Service worker: makes the app start instantly and keep working offline.
//
// - The app shell (HTML/CSS/JS/icons/level data) is cached when a new version installs.
// - Voice clips are cached the first time they are fetched and then never re-downloaded
//   (their file names contain a hash of their text, so a changed clip gets a new name).
// - Level data is network-first so new content shows up, with the cache as a fallback.
//
// The two lines between the markers are generated by `npm run build` (tools/build-precache.mjs).

/* precache:start */
const VERSION = 'dev';
const SHELL = ['./', 'index.html'];
/* precache:end */

const SHELL_CACHE = `shell-${VERSION}`;
const MEDIA_CACHE = 'media-v1';

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      .then((cache) => cache.addAll(SHELL.map((url) => new Request(url, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('shell-') && k !== SHELL_CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.includes('/assets/audio/')) event.respondWith(cacheFirst(req));
  else if (url.pathname.includes('/assets/data/')) event.respondWith(networkFirst(req));
  else event.respondWith(shell(req));
});

async function cacheFirst(req) {
  const hit = await caches.match(req.url); // any cache: the guide's lines live in the shell cache
  if (hit) return hit;
  const res = await fetch(req.url);
  if (res.ok && res.status === 200) {
    const cache = await caches.open(MEDIA_CACHE);
    cache.put(req.url, res.clone());
  }
  return res;
}

async function networkFirst(req) {
  const cache = await caches.open(MEDIA_CACHE);
  try {
    const res = await fetch(req, { cache: 'no-cache' });
    if (res.ok) cache.put(req.url, res.clone());
    return res;
  } catch (err) {
    const hit = (await cache.match(req.url)) || (await caches.match(req, { ignoreSearch: true }));
    if (hit) return hit;
    throw err;
  }
}

async function shell(req) {
  const hit = await caches.match(req, { ignoreSearch: true });
  if (hit) return hit;
  try {
    return await fetch(req);
  } catch (err) {
    if (req.mode === 'navigate') {
      const index = await caches.match('index.html');
      if (index) return index;
    }
    throw err;
  }
}
